from roman import to_int


def test_additive():
    assert to_int("III") == 3


def test_subtractive():
    assert to_int("IV") == 4
    assert to_int("IX") == 9


def test_multi_part():
    assert to_int("LVIII") == 58


def test_large_with_subtraction():
    assert to_int("MCMXCIV") == 1994

